import{_ as a,o as e,c as i,a2 as t}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Installation — Glacier Pack","description":"Install the Glacier Pack hub and any of the 24 Glacier addons on Pterodactyl Panel v1.12.x — prerequisites, per-addon install, verification, troubleshooting and uninstall.","frontmatter":{"title":"Installation — Glacier Pack","description":"Install the Glacier Pack hub and any of the 24 Glacier addons on Pterodactyl Panel v1.12.x — prerequisites, per-addon install, verification, troubleshooting and uninstall.","outline":"deep"},"headers":[],"relativePath":"glacier-pack/getting-started/installation.md","filePath":"glacier-pack/getting-started/installation.md","lastUpdated":null}'),n={name:"glacier-pack/getting-started/installation.md"};function r(l,s,o,d,h,p){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Glacier Pack installs as <strong>standalone packages</strong> — self-contained directories that mirror your panel root, each with an idempotent installer. There is no Blueprint step, no daemon on your nodes, and no core-file replacement. This guide covers prerequisites, installing the hub (required), adding addons, verification, and removal.</p><hr><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Minimum</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Pterodactyl Panel</strong></td><td>v1.12.x</td><td>Laravel 11 panel. The standard panel cron (<code>* * * * * php artisan schedule:run</code>) should be running — several addons schedule work through it.</td></tr><tr><td><strong>PHP</strong></td><td>8.2+</td><td>Same version the panel runs on.</td></tr><tr><td><strong>Root access</strong></td><td>Yes</td><td>Shell access to the panel host; the installer writes into the panel directory and resets ownership to the web user.</td></tr><tr><td><strong>Panel admin</strong></td><td>root admin</td><td>The hub and all addon admin surfaces are root-admin only.</td></tr></tbody></table><p>Some addons have extra prerequisites — see the <a href="#per-addon-install-notes">per-addon notes</a> below (RCON, a Cloudflare token, <code>mysql</code> client binaries, and so on).</p><h3 id="quick-dependency-check" tabindex="-1">Quick dependency check <a class="header-anchor" href="#quick-dependency-check" aria-label="Permalink to &quot;Quick dependency check&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Panel version (run from the panel root)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># PHP version (8.2+ required)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Panel cron registered</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">crontab</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schedule:run</span></span></code></pre></div><hr><h2 id="step-1-—-install-the-hub-required" tabindex="-1">Step 1 — Install the hub (required) <a class="header-anchor" href="#step-1-—-install-the-hub-required" aria-label="Permalink to &quot;Step 1 — Install the hub (required)&quot;">​</a></h2><p>The <strong>Glacier Pack hub is the only admin surface</strong> for the whole family. Individual addons ship no admin pages of their own — install the hub first, or your addons will have nowhere to be managed from.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> glacier-pack</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/install.sh</span></span></code></pre></div><p>The installer:</p><ol><li>Copies <code>PanelFiles/</code> into your panel root (<code>$PTERODACTYL_DIRECTORY</code>, default <code>/var/www/pterodactyl</code> — export it first if your panel lives elsewhere).</li><li>Registers <code>Pterodactyl\\Providers\\GlacierPackServiceProvider</code> in <code>config/app.php</code> (marker comment <code>// pterodactylglacierpack</code>).</li><li>Injects the <strong>Glacier Pack</strong> sidebar link into <code>resources/views/layouts/admin.blade.php</code> as a marker-delimited block.</li><li>Clears the config, route, view and application caches and resets ownership to <code>www-data</code>.</li></ol><p>The installer is <strong>idempotent</strong> — safe to re-run, and you <em>should</em> re-run it after any panel update that overwrites <code>config/app.php</code> or the admin layout.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The hub needs <strong>no database migrations</strong> — its addon registry is a plain config file (<code>config/glacier-pack.php</code>).</p></div><hr><h2 id="step-2-—-install-addons" tabindex="-1">Step 2 — Install addons <a class="header-anchor" href="#step-2-—-install-addons" aria-label="Permalink to &quot;Step 2 — Install addons&quot;">​</a></h2><p>Every addon installs the same way, from its own directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> recycle-bin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/install.sh</span></span></code></pre></div><p>Each addon&#39;s installer copies its <code>PanelFiles/</code> tree over the panel root, registers the addon&#39;s service provider, runs its database migrations (<code>php artisan migrate --force --no-interaction</code>), clears caches, and fixes ownership. Re-running an installer is always safe.</p><p>Set a non-standard panel path or web user before running:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PTERODACTYL_DIRECTORY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/srv/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PTERODACTYL_WEB_USER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nginx   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># default: www-data</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/install.sh</span></span></code></pre></div><p>Addons are independent — install any subset, in any order, and they appear in the hub rail as they land.</p><h3 id="per-addon-install-notes" tabindex="-1">Per-addon install notes <a class="header-anchor" href="#per-addon-install-notes" aria-label="Permalink to &quot;Per-addon install notes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Addon</th><th>Extra step or requirement</th></tr></thead><tbody><tr><td><strong>Recycle Bin</strong></td><td>Requires a <strong>frontend rebuild</strong>: <code>yarn build:production</code> after install (and again after uninstall). Needs Node.js, Yarn and Python 3 on the host.</td></tr><tr><td><strong>Node Stats</strong></td><td>Needs a Supervisor queue worker on the <code>nodeanalytics</code> queue — run the bundled <code>data/install-queue-worker.sh</code> after install.</td></tr><tr><td><strong>Player Manager</strong></td><td>Each managed server needs <code>enable-rcon=true</code>, <code>rcon.port</code> and <code>rcon.password</code> in <code>server.properties</code>, with the RCON port reachable from the panel host.</td></tr><tr><td><strong>Subdomain Manager</strong></td><td>Needs a Cloudflare API token (Zone / DNS / Edit) and the Zone ID of each domain you attach.</td></tr><tr><td><strong>Database Manager</strong></td><td>Needs <code>mysqldump</code> and <code>mysql</code> client binaries on the panel host (Debian/Ubuntu: <code>apt install default-mysql-client</code>).</td></tr><tr><td><strong>Backup Pro</strong></td><td>Needs a queue worker on the stock <code>standard</code> queue (the panel&#39;s <code>pteroq</code> service covers this) and an S3-compatible bucket.</td></tr><tr><td><strong>Server Importer</strong></td><td>Needs an Application API key (<code>ptla_…</code>) on the <em>source</em> panel with read access to servers, users, nodes, nests and eggs.</td></tr><tr><td><strong>Plugin / Mod / Modpack installers</strong></td><td>Panel needs outbound HTTPS to the catalogue APIs (<code>api.modrinth.com</code>, <code>api.curseforge.com</code>, …); nodes must reach the content CDNs. CurseForge requires an API key.</td></tr><tr><td><strong>Permission Manager</strong></td><td>Before uninstalling, remove members or run <code>php artisan permgr:sync</code> so no provisioned subusers are left behind.</td></tr></tbody></table><p>All remaining addons work out of the box after <code>install.sh</code>.</p><hr><h2 id="step-3-—-verify-the-install" tabindex="-1">Step 3 — Verify the install <a class="header-anchor" href="#step-3-—-verify-the-install" aria-label="Permalink to &quot;Step 3 — Verify the install&quot;">​</a></h2><h3 id="_1-routes-registered" tabindex="-1">1. Routes registered <a class="header-anchor" href="#_1-routes-registered" aria-label="Permalink to &quot;1. Routes registered&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route:list</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> glacier-pack</span></span></code></pre></div><p>Expected: the hub route <code>GET /admin/glacier-pack</code>. For each installed addon, its <strong>action</strong> routes appear too — addons ship no <code>GET /admin/&lt;addon&gt;</code> page routes of their own by design.</p><h3 id="_2-providers-registered" tabindex="-1">2. Providers registered <a class="header-anchor" href="#_2-providers-registered" aria-label="Permalink to &quot;2. Providers registered&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ServiceProvider::class&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config/app.php</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;pterodactyl&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config/app.php</span></span></code></pre></div><p>Each installed addon adds one marker-commented provider line to <code>config/app.php</code>.</p><h3 id="_3-open-the-hub" tabindex="-1">3. Open the hub <a class="header-anchor" href="#_3-open-the-hub" aria-label="Permalink to &quot;3. Open the hub&quot;">​</a></h3><p>Sign in as a root admin and open <strong>Admin → Glacier Pack</strong>, or browse directly to:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://your-panel.example/admin/glacier-pack</span></span></code></pre></div><p>The rail lists all 23 addons in two groups; installed addons open their pane, addons without files on the panel show a fallback card.</p><h3 id="_4-save-smoke-test" tabindex="-1">4. Save smoke test <a class="header-anchor" href="#_4-save-smoke-test" aria-label="Permalink to &quot;4. Save smoke test&quot;">​</a></h3><p>Open any installed addon&#39;s pane, change a setting, and save. You should land back on the same pane with the green <strong>Settings saved.</strong> banner.</p><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="provider-not-registered" tabindex="-1">Provider not registered <a class="header-anchor" href="#provider-not-registered" aria-label="Permalink to &quot;Provider not registered&quot;">​</a></h3><p><strong>Symptom:</strong> <code>route:list</code> shows nothing for an addon, or the panel errors with <code>Class ... not found</code>.</p><p><strong>Cause:</strong> the provider line in <code>config/app.php</code> was lost — usually a panel update overwrote the file, or caches are stale.</p><p><strong>Fix:</strong> re-run the addon&#39;s installer (it is idempotent), then clear caches:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">addo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/install.sh</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config:clear</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route:clear</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view:clear</span></span></code></pre></div><h3 id="blank-or-missing-pane-in-the-hub" tabindex="-1">Blank or missing pane in the hub <a class="header-anchor" href="#blank-or-missing-pane-in-the-hub" aria-label="Permalink to &quot;Blank or missing pane in the hub&quot;">​</a></h3><p><strong>Symptom:</strong> the rail entry shows a dot and the pane renders a &quot;Settings UI not linked yet&quot; card.</p><p><strong>Cause:</strong> the addon&#39;s view files are not on the panel — the <code>PanelFiles/</code> copy never happened or was reverted.</p><p><strong>Fix:</strong> re-run the addon&#39;s <code>data/install.sh</code>, then <code>php artisan view:clear</code>.</p><h3 id="stale-view-or-config-cache-after-installing" tabindex="-1">Stale view or config cache after installing <a class="header-anchor" href="#stale-view-or-config-cache-after-installing" aria-label="Permalink to &quot;Stale view or config cache after installing&quot;">​</a></h3><p><strong>Symptom:</strong> changes do not appear, old pages still render, or new routes 404.</p><p><strong>Fix:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config:clear</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route:clear</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view:clear</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cache:clear</span></span></code></pre></div><h3 id="sidebar-link-missing-after-a-panel-update" tabindex="-1">Sidebar link missing after a panel update <a class="header-anchor" href="#sidebar-link-missing-after-a-panel-update" aria-label="Permalink to &quot;Sidebar link missing after a panel update&quot;">​</a></h3><p>Panel updates can overwrite <code>resources/views/layouts/admin.blade.php</code> and <code>config/app.php</code>. Re-run the hub&#39;s installer — it re-applies the marker-delimited blocks without duplicating them:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> glacier-pack</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/install.sh</span></span></code></pre></div><h3 id="scheduled-work-not-running-alerts-backups-uptime-expiry" tabindex="-1">Scheduled work not running (alerts, backups, uptime, expiry) <a class="header-anchor" href="#scheduled-work-not-running-alerts-backups-uptime-expiry" aria-label="Permalink to &quot;Scheduled work not running (alerts, backups, uptime, expiry)&quot;">​</a></h3><p><strong>Symptom:</strong> Resource Alerts never fire, Backup Pro uploads sit pending, uptime graphs stay flat.</p><p><strong>Fix:</strong> confirm the standard panel cron exists and the queue worker is up:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">crontab</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schedule:run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pteroq</span></span></code></pre></div><p>Backup Pro additionally needs a worker on the <code>standard</code> queue; Node Stats needs its own <code>nodeanalytics</code> worker (<code>data/install-queue-worker.sh</code>).</p><hr><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><p>Every addon ships <code>data/remove.sh</code>, run from the addon directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> recycle-bin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/remove.sh</span></span></code></pre></div><p>The remover de-registers the service provider, removes the injected marker-delimited blocks, and clears caches. Copied files are left in place; the remover prints the exact paths to delete manually if you want them gone.</p><p>Addons with database tables keep their data by default. Most removers accept an explicit purge flag to drop it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/remove.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --purge-data</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # or --drop-table / --purge-tables / --purge-settings, per addon</span></span></code></pre></div><p>Check the addon&#39;s own <code>INSTALL.md</code> for the exact flag.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Purging is irreversible. Recycle Bin trash contents, Backup Pro archive records, Login Activity history, Resource Alerts history, and Staff Requests grants are all lost with their tables. Approved Staff Requests created <strong>real subuser rows</strong> — uninstalling does not remove already-granted subusers. For Permission Manager, remove members (or run <code>php artisan permgr:sync</code>) <em>before</em> removing the provider so no provisioned subusers remain.</p></div><p>To remove the hub itself:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> glacier-pack</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/remove.sh</span></span></code></pre></div><p>This removes the provider registration and the sidebar block, then clears caches. Remove the hub <strong>last</strong> — while it is installed it is the only admin surface for every pack addon.</p><hr><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next?&quot;">​</a></h2><ul><li><strong><a href="./quick-start">Quick Start →</a></strong> — hub plus three starter addons in minutes.</li><li><strong><a href="./../user-guide/dashboard">The Hub Dashboard →</a></strong> — a tour of the unified admin UI.</li><li><strong><a href="./../configuration/reference">Configuration Reference →</a></strong> — every setting, every default.</li></ul>`,79)])])}const g=a(n,[["render",r]]);export{k as __pageData,g as default};
